<script setup>import {ref} from 'vue';const emit=defineEmits(['submit']);const title=ref(''),category=ref('学习'),minutes=ref(25),busy=ref(false);async function submit(){if(!title.value.trim()||busy.value)return;busy.value=true;try{emit('submit',{title:title.value,category:category.value,minutes:minutes.value});await new Promise(r=>setTimeout(r,350));title.value=''}finally{busy.value=false}}</script><template><form class="task-form" @submit.prevent="submit"><label class="full">任务名称<input v-model="title" required placeholder="例如：完成英语单词复习"/></label><label>任务类型<select v-model="category"><option>学习</option><option>编程</option><option>阅读</option><option>语言</option><option>其他</option></select></label><label>预计时长<select v-model.number="minutes"><option :value="15">15 分钟</option><option :value="25">25 分钟</option><option :value="30">30 分钟</option><option :value="45">45 分钟</option><option :value="60">60 分钟</option></select></label><button class="primary full" :disabled="busy">{{busy?'正在添加…':'＋ 添加学习任务'}}</button></form></template>